command:
$ErrorActionPreference = "Stop"
git fetch origin main work/high-contrast-acceptance --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "fd2bda4d26a9d777f2ee17eb2fed5ab507174e25") { throw "main moved" }
if ((git rev-parse origin/work/high-contrast-acceptance).Trim() -ne "fb530bdbc2cf327c6d3020bc5ddc8467734ec8ea") { throw "candidate moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/high-contrast-acceptance origin/work/high-contrast-acceptance
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "fb530bdbc2cf327c6d3020bc5ddc8467734ec8ea") { throw "candidate mismatch" }
python -X utf8 -m py_compile tests\winui\test_high_contrast_contract.py
if ($LASTEXITCODE -ne 0) { throw "High Contrast contract syntax failed" }
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }
python -X utf8 tests\winui\test_owned_accessibility_layout_gui.py Release
if ($LASTEXITCODE -ne 0) { throw "owned accessibility layout smoke failed" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "HIGH_CONTRAST_ADAPTIVE_RESOURCE_SMOKE_PASS"
